-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , a AS (SELECT d.membro_tipo,d.product_category_name,count(*) itens,sum(i.price) price,sum(i.freight_value) freight_value FROM i LEFT JOIN gold.dim_produtos d ON d.produto_sk=i.produto_sk GROUP BY 1,2) SELECT rank() OVER(ORDER BY price DESC NULLS LAST) posicao,a.* FROM a ORDER BY price DESC NULLS LAST,product_category_name NULLS FIRST,membro_tipo;
